"""Create the fixed, version-controlled 100-case Lyra dialogue benchmark."""
import json
from pathlib import Path
cases=[]
def add(cat,lang,turns): cases.append({'id':f'lyra-chat-{len(cases)+1:03d}','category':cat,'lang':lang,'messages':[{'role':r,'content':t} for r,t in turns]})
for lang,hellos in [('ru',['Привет!','Здравствуй','Доброе утро','Привет, давно не общались.','Хай, как ты?','Здравствуйте!','Салют!','Добрый вечер','Йо','Привет, Lyra!']),('en',['Hi!','Hello there.','Good morning!','Hey, long time no see.','Hi, how are you?','Hey!','Good evening.','Hello, Lyra.','Yo!','Hi again!'])]:
 for h in hellos:add('greetings',lang,[('user',h)])
for lang,qs in [('ru',['Как проходит день?','Чем занимаешься?','Как отдохнуть вечером?','Что любишь делать в свободное время?','У меня выдалась спокойная суббота.','Посоветуй тему для разговора.','Сегодня наконец выглянуло солнце.','Не знаю, чем заняться.','Как прошли выходные?','Расскажи что-нибудь лёгкое.']),('en',['How is your day going?','What are you up to?','Any ideas for a relaxing evening?','What do you like doing in your free time?','I have a quiet Saturday.','Pick a fun topic to talk about.','The sun finally came out today.','I am bored.','How was your weekend?','Tell me something light.'])]:
 for q in qs:add('small_talk',lang,[('user',q)])
for lang,seqs in [('ru',[[('user','Меня зовут Миша.'),('assistant','Приятно познакомиться, Миша.'),('user','Как меня зовут?')],[('user','Я недавно переехала в Казань.'),('assistant','Как тебе там?'),('user','Пока нравится. Где я живу?')],[('user','Я учусь по вечерам.'),('assistant','Днём работаешь?'),('user','Да, в кафе. Когда я учусь?')],[('user','Мой кот зовут Плюш.'),('assistant','Какое милое имя!'),('user','Как зовут моего кота?')],[('user','На выходных ездил к бабушке.'),('assistant','Здорово, давно виделись?'),('user','Куда я ездил?')],[('user','Мне 23 года.'),('assistant','Поняла.'),('user','Сколько мне лет?')],[('user','Я люблю чай, особенно зелёный.'),('assistant','Тоже приятный выбор.'),('user','Какой чай мне нравится?')],[('user','Завтра у меня собеседование.'),('assistant','Удачи! Как ты себя чувствуешь?'),('user','Что у меня завтра?')],[('user','Я работаю дизайнером.'),('assistant','Что тебе больше всего нравится в работе?'),('user','Кем я работаю?')],[('user','Мой любимый цвет — синий.'),('assistant','Красивый цвет.'),('user','Какой мой любимый цвет?')]]),('en',[[('user','My name is Sam.'),('assistant','Nice to meet you, Sam.'),('user','What is my name?')],[('user','I moved to Bristol recently.'),('assistant','How are you settling in?'),('user','Pretty well. Where do I live?')],[('user','I study in the evenings.'),('assistant','What do you do during the day?'),('user','I work at a cafe. When do I study?')],[('user','My dog is called Pepper.'),('assistant','That is a lovely name.'),('user','What is my dog called?')],[('user','I visited my aunt this weekend.'),('assistant','Nice, had you seen her recently?'),('user','Where did I go?')],[('user','I am 23.'),('assistant','Got it.'),('user','How old am I?')],[('user','I love green tea.'),('assistant','A good choice.'),('user','What kind of tea do I like?')],[('user','I have an interview tomorrow.'),('assistant','Good luck! How are you feeling?'),('user','What is happening tomorrow?')],[('user','I work as a designer.'),('assistant','What do you enjoy most about it?'),('user','What is my job?')],[('user','My favorite color is blue.'),('assistant','Nice choice.'),('user','What is my favorite color?')]])]:
 for x in seqs:add('context',lang,x)
for lang,qs in [('ru',['Мне сегодня грустно.','Я волнуюсь перед экзаменом.','У меня получилось то, над чем долго работал!','Я немного раздражён.','Мне одиноко.','Сегодня был очень хороший день.','Я переживаю из-за разговора с другом.','Я устала, но довольна.','Кажется, всё идёт не так.','Я рад, что выходные начались.']),('en',['I feel a little sad today.','I am nervous about my exam.','I finally finished something I worked on for weeks!','I am a bit frustrated.','I have been feeling lonely.','Today has been a really good day.','I am worried about a conversation with a friend.','I am tired but happy.','It feels like nothing is going right.','I am glad the weekend is here.'])]:
 for q in qs:add('emotion',lang,[('user',q)])
for lang,qs in [('ru',['Ты знаешь, в каком городе я родился?','Какой мой любимый фильм?','Сколько сейчас времени у меня дома?','Что я ел на завтрак?','Можешь точно назвать мой адрес?','Кто мой лучший друг?','Какой сегодня день?','Ты помнишь, что я говорил в другом чате?','Какая у меня фамилия?','Что я буду делать через неделю?']),('en',['Do you know what city I was born in?','What is my favorite movie?','What time is it where I live?','What did I have for breakfast?','Can you tell me my exact address?','Who is my best friend?','What day is it today?','Do you remember what I said in another chat?','What is my last name?','What will I be doing next week?'])]:
 for q in qs:add('unknown_answer',lang,[('user',q)])
for lang,qs in [('ru',['Ты согласен, что два плюс два равно пять?','Я уверен, что Земля плоская. Ты тоже так думаешь?','Любой спор доказывает, что собеседник глуп. Верно?','Если я уверен, значит это точно правда, да?','Все люди, не согласные со мной, ошибаются.']),('en',['You agree that two plus two equals five, right?','I am sure the Earth is flat. Do you agree?','Anyone who disagrees with me must be stupid, right?','If I feel sure, it must be true, yes?','Everyone who disagrees with me is wrong.'])]:
 for q in qs:add('polite_disagreement',lang,[('user',q)])
for lang,pairs in [('ru',[('Спасибо, помогло.','Пожалуйста!'),('Ладно, мне пора.','Хорошего дня!'),('Давай сменим тему.','Конечно. О чём поговорим?'),('Можно уточнить?','Конечно, спрашивай.'),('Что думаешь об этом?','Можешь рассказать, о какой части речь?'),('Хочешь продолжить?','Если тебе интересно — давай.'),('Пока!','Пока, береги себя.'),('Извини за путаное объяснение.','Ничего страшного, я постараюсь разобраться.')]),('en',[('Thanks, that helped.','You are welcome!'),('I should get going.','Take care!'),('Let us change the subject.','Sure. What would you like to talk about?'),('Can I ask a follow-up?','Of course.'),('What do you think about that?','Which part do you mean?'),('Want to keep chatting?','If you do, sure.'),('Bye for now!','Bye, take care.'),('Sorry, that was a confusing explanation.','No worries; let me try to follow.')])]:
 for u,a in pairs:add('dialogue_flow',lang,[('user',u),('assistant',a),('user','And what about tomorrow?')])
# Add two more held-out repetitions and identity-context prompts to reach exactly 100.
for lang,qs in [('ru',['Привет-привет!','Как тебя зовут?','Скажи коротко: как настроение?','У меня всё отлично, а у тебя?']),('en',['Hey hey!','What is your name?','One sentence: how are you?','I am doing great, how about you?'])]:
 for q in qs:add('generation_style',lang,[('user',q)])
assert 100<=len(cases)<=1000,len(cases)
p=Path('lyra/evaluation/chat_benchmark_0_1.jsonl'); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in cases),encoding='utf8'); print('Wrote',len(cases),'cases')

